package app.space.notes.domain;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class ContentNamesTest {
 @Test public void richChecklistToTextKeepsCaptionIndentationAndMarks(){DocumentContent content=new DocumentContent(Arrays.asList(DocumentContent.Block.checklist("list","Shopping",Arrays.asList(new Note.Item("a","Milk",true,1,Arrays.asList(new Note.Mark("bold",0,4)))),false)));DocumentContent next=content.checklistToText("list");assertEquals("Shopping\n  Milk",next.block("list").text.text);assertEquals(11,next.block("list").text.marks.get(0).start);assertEquals(DocumentContent.Kind.CHECKLIST,content.block("list").kind);}
 @Test public void namesAreIndependentOfKindsAndSurviveMutations(){NoteImage image=new NoteImage(UUID.randomUUID().toString(),"Drawing","image/png",1,1,"iVBORw==");Note note=Note.create(1).images(Arrays.asList(image),2).namedContent("image:"+image.id,"Sketch",3).namedContent("reminder","Call Mum",3).namedContent("diagram","Plan",3);for(Note n:Arrays.asList(note.edit("a","b",4),note.convert(4),note.reminder(10000,4),note.withId("copy"),NoteOperations.duplicate(note,4),note.background(2,4),note.folder("Work",4),note.withContent(DocumentContent.fromLegacy(note),4))){assertEquals("Sketch",n.contentName("image:"+image.id,""));assertEquals("Drawing",n.images.get(0).name);assertTrue(n.matches("call mum"));}assertEquals(DocumentContent.Kind.DRAWING,DocumentContent.fromLegacy(note).blocks.get(1).kind);assertEquals("Sketch",DocumentContent.fromLegacy(note).blocks.get(1).name);}
 @Test public void identityAndResetAndBounds(){Note a=Note.create(1),b=a.namedContent("diagram","Plan",1);assertFalse(NoteMerge.same(a,b));assertTrue(NoteMerge.same(a,b.namedContent("diagram","",1)));assertThrows(IllegalArgumentException.class,()->a.namedContent("unknown","bad",2));assertThrows(IllegalArgumentException.class,()->a.namedContent("reminder","bad\nname",2));assertThrows(UnsupportedOperationException.class,()->b.contentNames.put("diagram","bad"));}
 @Test public void removingImagePrunesItsName(){NoteImage image=new NoteImage(UUID.randomUUID().toString(),"Drawing","image/png",1,1,"iVBORw==");Note note=Note.create(1).images(Arrays.asList(image),2).namedContent("image:"+image.id,"Sketch",3);assertTrue(note.images(Collections.emptyList(),4).contentNames.isEmpty());}
}
